mapper.insert:
INSERT INTO event_outbox (
    id, event_id, event_type, aggregate_type, aggregate_id, payload, status, retry_count, next_retry_at, last_error
) VALUES (
    #{id}, #{eventId}, #{eventType}, #{aggregateType}, #{aggregateId}, #{payload}, #{status}, #{retryCount},
    #{nextRetryAt}, #{lastError}
)

mapper.select:
SELECT id, event_id, event_type, aggregate_type, aggregate_id, payload, status, retry_count,
       next_retry_at, locked_by, locked_until, last_error, created_at, updated_at
FROM event_outbox
WHERE (
    status IN (0, 2)
    AND (next_retry_at IS NULL OR next_retry_at <= #{now})
) OR (
    status = 3
    AND locked_until IS NOT NULL
    AND locked_until <= #{now}
)
ORDER BY created_at ASC, id ASC
LIMIT #{limit}

mapper.update:
UPDATE event_outbox
SET status = 3,
    locked_by = #{workerId},
    locked_until = #{lockedUntil},
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND (
      (
          status IN (0, 2)
          AND (next_retry_at IS NULL OR next_retry_at <= #{now})
      ) OR (
          status = 3
          AND locked_until IS NOT NULL
          AND locked_until <= #{now}
      )
  )
